/* LeaveFlowMapper.selectOccupiedLeaveDaysOnDate */
SELECT COALESCE(SUM(
         CASE WHEN U.USE_UNIT_TYPE = '00' THEN 1.0 ELSE U.LEAVE_DAYS END
       ), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE   <=  #{workYmd}
   AND U.END_DATE     >=  #{workYmd}

/* LeaveFlowMapper.countOverlappingTimeLeaveOnDate */
SELECT COUNT(1)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD       = #{cmpnyCd}
   AND U.USER_CD        = #{userCd}
   AND U.LEAVE_STATUS   = 'CONFIRMED'
   AND U.DEL_YN         = 'N'
   AND U.START_DATE     = #{workYmd}
   AND U.USE_UNIT_TYPE IN ('02', '03', '04')
   AND U.START_TIME IS NOT NULL
   AND U.END_TIME   IS NOT NULL
   AND U.START_TIME  <  #{endTime}
   AND U.END_TIME    >  #{startTime}

/* LeaveFlowMapper.countValidApprovers */
SELECT COUNT(DISTINCT U.USER_CD)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS  = '01'
   AND U.AUTH_CD != 'system'
   AND U.USER_CD IN

     #{uc}

/* LeaveFlowMapper.selectTotalUsedDays */
SELECT IFNULL(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'

/* LeaveFlowMapper.selectFiscalUsedDays */
SELECT IFNULL(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE  >= #{fiscalStartYmd}
   AND U.START_DATE  <  #{fiscalEndYmdExclusive}

/* LeaveFlowMapper.selectDeductibleGrant */
SELECT
      G.GRANT_ID   AS grantId
    , G.GRANT_DAYS AS grantDays
    , G.USED_DAYS  AS usedDays
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) >= #{neededDays}
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC
 LIMIT 1
 FOR UPDATE

/* LeaveFlowMapper.selectAutoDeductibleGrant */
SELECT
      G.GRANT_ID AS grantId
    , G.LEAVE_CD AS leaveCd
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD IN
   #{cd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) >= #{neededDays}
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC, G.GRANT_ID ASC
 LIMIT 1
 FOR UPDATE

/* LeaveFlowMapper.countAnyFullDayLeaveOnCell */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'
   AND U.USE_UNIT_TYPE = '00'
   AND U.START_DATE   <= #{workYmd}
   AND U.END_DATE     >= #{workYmd}

