/* LeaveFlowMapper.insertLeaveReq */
INSERT INTO TB_USER_ATTD_REQ (
      REQ_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , REQ_STATUS
    , REQ_REASON
    , WORK_YMD
    , NODE_CD
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , LEAVE_TYPE
    , LEAVE_DAYS
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{reqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , '05'
    , #{reqStatus}
    , #{reqReason}
    , #{workYmd}
    , #{nodeCd}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{leaveType}
    , #{leaveDays}
    , 'N'
    , #{insertNo}
    , NOW()
)

